import { useState, component, useEffect, useLayoutEffect, useRef } from 'haunted';
import { html, css } from 'lit';
import { ref, createRef } from 'lit/directives/ref.js';
import { keyed } from 'lit/directives/keyed.js';

const KEYCODES = {
  ENTER: 'Enter',
  TAB: 'Tab',
  BACKSPACE: 'Backspace',
}

// TODO: Already this needs some refactoring ewww
// Styles are kind of unreadable (generated by claude)
// & keyboard logic might be better off moved to the parent
// This cell should not really care about

const styles = css`
  civ-table-cell {
    display: block;
    width: 100%;
    height: 100%;
    box-sizing: border-box;

        div {
            width: 100%;
            height: 100%;
            min-height: 1em;
            display: flex;
            align-items: stretch;
        }

        span {
            flex: 1;
            width: 100%;
            height: 100%;
            display: block;
            min-height: 1em;
            box-sizing: border-box;
            border: 2px solid transparent;
            padding: 0.4rem;
            white-space: normal;
            word-break: break-word;
            overflow-wrap: break-word;
        }

        span.cell-content[contenteditable="true"]:focus {
            box-sizing: border-box;
            outline: 2px solid rgb(var(--catppuccin-sapphire));
        }
        div.tag-list:focus-within {
            outline: 2px solid rgb(var(--catppuccin-sapphire));
        }

        div:focus {
            outline: 1px solid rgb(var(--catppuccin-sapphire));
        }

    .tag-list {
        display: flex;
        flex-direction: row;
        flex-wrap: wrap;
        align-items: flex-start;
        align-content: flex-start;
        gap: 0.25rem;
        padding: 0.4rem;
        width: 100%;
        height: 100%;
        box-sizing: border-box;
    }

    .tag-list button:hover {
        background: rgb(var(--catppuccin-sapphire), 0.2);
        border-color: rgb(var(--catppuccin-crust));
    }

    .tag-list button {
        appearance: none;
        border: 1px solid rgb(var(--catppuccin-crust));
        background: rgb(var(--catppuccin-base));
        border-radius: 999px;
        padding: 0.1rem 0.35rem 0.1rem 0.5rem;
        font-size: 0.72rem;
        font-family: inherit;
        cursor: pointer;
        color: #333;
        width: fit-content;      /* shrinks to content */
        max-width: 200px;        /* but won't exceed this */
        display: inline-flex;
        align-items: center;
        gap: 0;
        line-height: 1;
    }

    .tag-list button span.tag-label {
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
        min-width: 0;
        margin-right: 0.2rem;
        flex: auto;
    }

    .tag-list button span.tag-remove {
        flex: content;
    }

    .tag-input {
        flex-basis: 100%;
        min-height: 1.2em;
        outline: none;
        border: none;
        background: transparent;
        padding: 0;
        font-size: 0.8rem;
        font-family: inherit;
        color: inherit;
        white-space: normal;
        word-break: break-word;
        overflow-wrap: break-word;
    }

    .tag-input:empty::before {
        content: attr(data-placeholder);
        color: #aaa;
        pointer-events: none;
    }
  }
`;

function TableCell({
  identifier,
  rowIndex,
  colIndex,
  field,
  type,
  format,
  value,
  focused,
  editing
}) {
  const contentEditableRef = createRef()
  const divRef = createRef();

  useLayoutEffect(() => {
    if (editing) {
      const el = contentEditableRef.current;
      if (el) {
        el.focus();
        // Move caret to end
        const range = document.createRange();
        range.selectNodeContents(el);
        range.collapse(false);
        const sel = window.getSelection();
        sel.removeAllRanges();
        sel.addRange(range);
      }
    } else if (focused) {
      divRef.current.focus();
    }
  }, [focused, editing]);

  function renderSingleCell() {
    if (!editing) {
      return keyed('display', html`
                <span class="cell-content">${value}</span>
            `);
    }
    return keyed('edit', html`
            <span
                class="cell-content"
                contenteditable="true"
                ${ref(el => {
      contentEditableRef.current = el;
      if (el && !el.dataset.initialized) {
        el.innerText = value ?? '';
        el.dataset.initialized = 'true';
      }
    })}
            ></span>
        `);
  }

  function handleAddItem(e, newItem) {
    if (newItem) {
      const newList = [...currentList, newItem];
      e.currentTarget.dispatchEvent(new CustomEvent('data-change', {
        detail: { identifier, field, value: newList, row: rowIndex, col: colIndex },
        bubbles: true,
        composed: true
      }));
      e.target.innerText = '';
    }
  }

  function handleRemoveItem(e, index) {
    const currentList = Array.isArray(value) ? value : [];
    const newList = currentList.filter((_, i) => i !== index);
    e.currentTarget.dispatchEvent(new CustomEvent('data-change', {
      detail: { identifier, field, value: newList, row: rowIndex, col: colIndex },
      bubbles: true,
      composed: true
    }));
  }

  function handleListInputKeyDown(e, currentList) {
    if (!editing) { return; }

    if (e.key === KEYCODES.ENTER) {
      e.preventDefault();
      const newItem = e.target.innerText.trim();
      handleAddItem(e, newItem)
    } else if (e.key === KEYCODES.BACKSPACE) {
      if (currentList.length === 0) {
        return
      }

      handleRemoveItem(e, currentList.length - 1)
    }
  }

  function renderListCell() {
    const editList = value && Array.isArray(value) ? value : [];

    const displayWithFormat = item => {
      switch (format) {
        case 'phone':
          return html`<a href="tel:${item}" class="tag-link" tabindex="-1">${item}</a>`;
        case 'email':
          return html`<a href="mailto:${item}" class="tag-link" tabindex="-1">${item}</a>`;
        default: // Regular link
          return html`<a href="${item}" target="_blank" rel="noopener noreferrer" class="tag-link" tabindex="-1">${item}</a>`;
      }
    }

    return html`
            <div class="tag-list ${editing ? 'editing' : ''}">
                ${editList.map((item, i) => editing
      ? html`
                        <button type="button" @click=${() => handleRemoveItem(i)}>
                            <span class="tag-label">${item}</span>
                            <span class="tag-remove">×</span>
                        </button>`
      : displayWithFormat(item)
    )}
                ${editing ? html`
                    <span
                        class="tag-input"
                        contenteditable="true"
                        data-placeholder="Add…"
                        @keydown=${e => { handleListInputKeyDown(e, editList) }}
                        ${ref(el => {
      contentEditableRef.current = el;
    })}
                    ></span>
                ` : ''}
            </div>
        `;
  }

  function renderImageCell() {
    return html`
            <div style="width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; padding: 0.25rem; box-sizing: border-box;">
                ${value
        ? html`<img src="${value}" alt="Profile image" style="
                        width: min(100%, 100cqh, 4rem);
                        height: min(100%, 100cqh, 4rem);
                        border-radius: 50%;
                        object-fit: cover;
                        object-position: center;
                        display: block;
                        flex-shrink: 0;
                      " />`
        : html`<div style="
                        width: min(100%, 100cqh, 4rem);
                        height: min(100%, 100cqh, 4rem);
                        border-radius: 50%;
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        flex-shrink: 0;
                        font-size: 0.7rem;
                        color: #aaa;
                      ">?</div>`
      }
            </div>
        `;
  }

  function renderCell() {
    switch (type) {
      case 'multiple':
        return renderListCell();
      case 'image':
        return renderImageCell();
      default:
        return renderSingleCell();
    }
  }

  return html`
        <style>${styles}</style>
        <div
            tabIndex="-1"
            data-col=${colIndex} 
            data-row=${rowIndex} 
            data-field=${field} 
            ${ref(el => {
    divRef.current = el;
  })}
        >
            ${renderCell()}
        </div>
    `;
}

customElements.define('civ-table-cell', component(TableCell, { observedAttributes: ['identifier', 'rowIndex', 'colIndex', 'field', 'value'], useShadowDOM: false }));